<script setup lang="ts">
import{ref}from'vue';import Taro,{useDidShow}from'@tarojs/taro';import PageShell from '@/components/PageShell.vue';import SectionCard from '@/components/SectionCard.vue';import StatePanel from '@/components/StatePanel.vue';import StatusBadge from '@/components/StatusBadge.vue';import{api}from'@/lib/api';import{errorMessage}from'@/lib/errors';import{shortDate,yuan}from'@/lib/format';import type{ConsumerOrder,PurchaseIntent}from'@/lib/types';
const orders=ref<ConsumerOrder[]>([]),intents=ref<PurchaseIntent[]>([]),loading=ref(true),error=ref('');async function load(){loading.value=true;error.value='';try{const[o,i]=await Promise.all([api.orders(),api.purchaseIntents()]);orders.value=o.data.orders;intents.value=i.data.intents.filter(v=>v.status==='proposed');}catch(e){error.value=errorMessage(e);}finally{loading.value=false;}}useDidShow(()=>{void load();});
const payment=(s:string)=>({pending:'待付款',paid:'已付款',unknown:'结果待核验',closed:'已关闭',failed:'付款失败'}[s]??s);const tone=(s:string)=>s==='paid'?'success':s==='unknown'?'warning':s==='pending'?'info':'neutral';
</script>
<template><PageShell title="订单与确认" subtitle="退出重登后仍可从这里恢复"><StatePanel v-if="loading" title="正在恢复本人状态"/><StatePanel v-else-if="error" title="订单暂时不可用" :detail="error" tone="error"><button class="secondary-button retry" @tap="load">重新加载</button></StatePanel><template v-else><text class="heading">等待你确认</text><view v-if="intents.length" class="list"><SectionCard v-for="v in intents" :key="v.purchaseIntentId" @tap="Taro.navigateTo({url:`/pages/purchase/detail?id=${v.purchaseIntentId}`})"><view class="row-between"><text class="title">{{v.offerName}}</text><StatusBadge label="待确认" tone="info"/></view><text class="meta">{{shortDate(v.plannedOn)}} · {{yuan(v.quotedAmountMinor)}} · 查看确认 ›</text></SectionCard></view><StatePanel v-else title="没有待确认意图" detail="从计划项目选择候选后，会先在这里等待你的确认。"/><text class="heading heading--orders">我的订单</text><view v-if="orders.length" class="list"><SectionCard v-for="v in orders" :key="v.orderId" @tap="Taro.navigateTo({url:`/pages/order/detail?id=${v.orderId}`})"><view class="row-between"><text class="title">{{v.itemName}}</text><StatusBadge :label="payment(v.paymentStatus)" :tone="tone(v.paymentStatus)"/></view><text class="amount">{{yuan(v.amountMinor)}}</text><text class="meta">{{shortDate(v.updatedAt)}} · {{v.environment==='simulation'?'本地模拟':'支付宝沙箱'}} · 查看详情 ›</text></SectionCard></view><StatePanel v-else title="还没有订单" detail="购买意图经你确认后才会建立订单。"/></template></PageShell></template>
<style lang="scss">@use '../../styles/tokens' as *;.retry{margin-top:18px}.heading{display:block;margin:4px 6px 12px;font-size:27px;font-weight:720}.heading--orders{margin-top:28px}.list{display:grid;gap:14px}.title{font-size:26px;font-weight:680}.amount,.meta{display:block}.amount{margin-top:18px;font-size:33px;font-weight:740}.meta{margin-top:9px;color:$text-secondary;font-size:21px}</style>
